// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue, uint256 initialDistr) public {
        // Restrict inputs to avoid overflows and satisfy require statements
        vm.assume(burnValue > 0 && burnValue <= 500000000e18 / 2);
        vm.assume(initialDistr > 0 && initialDistr <= 500000000e18 / 2);

        // First, call XBornID() to set initial balances
        c.XBornID();

        // Get initial totalDistributed after XBornID
        uint256 initialTotalDistributed = c.totalDistributed();

        // Amount to burn (must be <= balance of owner)
        uint256 burnAmt = bound(burnValue, 1, c.balanceOf(address(this)));

        // Burn tokens
        c.burn(burnAmt);

        // After burn, call XBornID() again (this is the distinguishing operation)
        c.XBornID();

        // After XBornID(), totalDistributed should be reset to initialTotalDistributed (because XBornID sets it to totalDistributed, but burn removed totalDistributed in reference)
        // Actually, XBornID does not change totalDistributed; it only sets balances[owner] = totalDistributed
        // The invariant is: totalDistributed after XBornID equals its value before the call (since XBornID doesn't modify totalDistributed)
        // After burn, in reference totalDistributed decreased, in mutant it didn't.
        // So after XBornID, totalDistributed remains whatever it was after burn operations.
        // So we compare totalDistributed after XBornID with expected based on reference.
        uint256 finalTotalDistributed = c.totalDistributed();

        // In reference: totalDistributed after burn = initialTotalDistributed - burnAmt
        // In mutant: totalDistributed after burn = initialTotalDistributed (unchanged)
        // After XBornID, totalDistributed stays that way.
        // So we assert that totalDistributed equals initialTotalDistributed - burnAmt (reference behavior)
        // But we can't know reference vs mutant, we need a general rule that holds on reference and fails on mutant.
        // The rule: totalDistributed after all operations equals initialTotalDistributed - burnAmt (because burn subtracts from totalDistributed in reference)
        c.totalDistributed(); // to avoid unused warning
        // Actually we need to check: totalDistributed decreased by burnAmt relative to initial
        // In reference: finalTotalDistributed == initialTotalDistributed - burnAmt
        // In mutant: finalTotalDistributed == initialTotalDistributed
        // So assertTrue(finalTotalDistributed == initialTotalDistributed - burnAmt)
        assertTrue(finalTotalDistributed == initialTotalDistributed - burnAmt, "totalDistributed should decrease by burn amount");
    }
}

